<?php

declare(strict_types=1);

namespace Tests\Unit\Crypto;

use App\Support\Crypto\PasswordHasher;
use App\Support\Crypto\SecretBox;
use App\Support\Crypto\SecretBoxException;
use App\Support\Crypto\Totp;
use App\Support\Razorpay\Signature;
use PHPUnit\Framework\TestCase;

/**
 * Cross-language parity against the Node application.
 *
 * `tests/Fixtures/node-parity.json` was generated by the Dhansree API's OWN compiled modules
 * (`apps/api/dist/auth/totp.js`, `secret-box.js`, `password-hasher.js` and
 * `payments/razorpay/razorpay-signature.js`) — not by a re-description of them. Regenerate it with
 * `scripts/regenerate-parity-fixtures.sh` if the Node side ever changes.
 *
 * These are the tests that decide whether the migration can reuse the existing database:
 *   - if the password tests pass, no administrator has to reset their password;
 *   - if the SecretBox tests pass, no administrator has to re-enrol their authenticator;
 *   - if the Razorpay tests pass, live webhooks will verify.
 *
 * They must run before any feature is built on top of them.
 */
final class NodeParityTest extends TestCase
{
    /** @return array<string, mixed> */
    private function fixtures(): array
    {
        $path = __DIR__.'/../../Fixtures/node-parity.json';
        $raw = file_get_contents($path);
        self::assertIsString($raw, "Missing fixture file: {$path}");

        $decoded = json_decode($raw, true);
        self::assertIsArray($decoded);

        return $decoded;
    }

    public function test_argon2_parameters_match_the_node_implementation(): void
    {
        $params = $this->fixtures()['argon2Params'];

        self::assertSame(PasswordHasher::MEMORY_COST, $params['memoryCost']);
        self::assertSame(PasswordHasher::TIME_COST, $params['timeCost']);
        self::assertSame(PasswordHasher::THREADS, $params['parallelism']);
    }

    public function test_php_verifies_password_hashes_produced_by_node(): void
    {
        $hasher = new PasswordHasher();

        foreach ($this->fixtures()['passwords'] as $case) {
            self::assertTrue(
                $hasher->verify($case['hash'], $case['password']),
                "PHP could not verify a Node-generated hash for: {$case['password']}",
            );
            self::assertFalse(
                $hasher->verify($case['hash'], $case['password'].'x'),
                'A wrong password was accepted',
            );
        }
    }

    public function test_php_produces_hashes_node_would_accept(): void
    {
        $hasher = new PasswordHasher();
        $hash = $hasher->hash('CorrectHorseBattery7!');

        // The Node side's own PHC_PATTERN, so a hash written by PHP is readable after a rollback.
        self::assertMatchesRegularExpression(
            '#^\$argon2id\$v=19\$m=19456,t=2,p=1\$[A-Za-z0-9+/]+\$[A-Za-z0-9+/]+$#',
            $hash,
        );
        self::assertTrue($hasher->verify($hash, 'CorrectHorseBattery7!'));
        self::assertFalse($hasher->needsRehash($hash));
    }

    public function test_malformed_hashes_verify_false_rather_than_throwing(): void
    {
        $hasher = new PasswordHasher();

        foreach (['', 'not-a-hash', '$argon2i$v=19$m=19456,t=2,p=1$abc$def', '$2y$10$abcdefgh'] as $bad) {
            self::assertFalse($hasher->verify($bad, 'anything'));
        }
    }

    public function test_php_decrypts_secret_box_values_sealed_by_node(): void
    {
        $fixtures = $this->fixtures()['secretBox'];
        $box = new SecretBox($fixtures['key']);

        self::assertTrue($box->available());

        foreach ($fixtures['cases'] as $case) {
            self::assertSame(
                $case['plaintext'],
                $box->open($case['sealed'], $case['label']),
                "Failed to open a Node-sealed value labelled {$case['label']}",
            );
        }
    }

    public function test_a_sealed_value_cannot_be_moved_to_another_row(): void
    {
        $fixtures = $this->fixtures()['secretBox'];
        $box = new SecretBox($fixtures['key']);
        $case = $fixtures['cases'][0];

        $this->expectException(SecretBoxException::class);
        $box->open($case['sealed'], 'admin-totp:999999');
    }

    public function test_a_sealed_value_from_another_key_is_refused(): void
    {
        $fixtures = $this->fixtures()['secretBox'];
        $other = new SecretBox(base64_encode(str_repeat("\x01", 32)));

        $this->expectException(SecretBoxException::class);
        $other->open($fixtures['cases'][0]['sealed'], $fixtures['cases'][0]['label']);
    }

    public function test_php_seals_values_it_can_reopen_in_the_node_envelope_format(): void
    {
        $box = new SecretBox(base64_encode(random_bytes(32)));
        $sealed = $box->seal('JBSWY3DPEHPK3PXP', 'admin-totp:7');

        $parts = explode('.', $sealed);
        self::assertCount(5, $parts, 'Envelope must be v1.<keyid>.<iv>.<tag>.<ciphertext>');
        self::assertSame(SecretBox::VERSION, $parts[0]);
        self::assertSame('JBSWY3DPEHPK3PXP', $box->open($sealed, 'admin-totp:7'));
    }

    public function test_an_unconfigured_key_refuses_rather_than_storing_plaintext(): void
    {
        $box = new SecretBox(null);
        self::assertFalse($box->available());

        $this->expectException(SecretBoxException::class);
        $box->seal('secret', 'admin-totp:1');
    }

    public function test_totp_codes_are_identical_to_the_node_implementation(): void
    {
        $fixtures = $this->fixtures()['totp'];

        self::assertSame(Totp::DIGITS, $fixtures['digits']);
        self::assertSame(Totp::PERIOD_SECONDS, $fixtures['period']);
        self::assertSame(Totp::WINDOW_STEPS, $fixtures['window']);

        foreach ($fixtures['cases'] as $case) {
            self::assertSame(
                $case['code'],
                Totp::code($case['secret'], $case['step']),
                "Code differs for secret={$case['secret']} step={$case['step']}",
            );
        }
    }

    public function test_totp_verification_accepts_the_window_and_refuses_replay(): void
    {
        $secret = 'JBSWY3DPEHPK3PXP';
        $at = new \DateTimeImmutable('@1700000000');
        $step = Totp::timeStep($at);

        // The current step is accepted and reported back.
        self::assertSame($step, Totp::verify($secret, Totp::code($secret, $step), $at, null));

        // One step either side is accepted (clock drift).
        self::assertSame($step - 1, Totp::verify($secret, Totp::code($secret, $step - 1), $at, null));
        self::assertSame($step + 1, Totp::verify($secret, Totp::code($secret, $step + 1), $at, null));

        // Two steps away is outside the window.
        self::assertNull(Totp::verify($secret, Totp::code($secret, $step - 2), $at, null));

        // A spent step cannot be replayed, even though the arithmetic still matches.
        self::assertNull(Totp::verify($secret, Totp::code($secret, $step), $at, $step));
    }

    public function test_totp_rejects_malformed_codes(): void
    {
        $at = new \DateTimeImmutable('@1700000000');

        foreach (['', '12345', '1234567', 'abcdef', '12 34 5'] as $bad) {
            self::assertNull(Totp::verify('JBSWY3DPEHPK3PXP', $bad, $at, null));
        }
    }

    public function test_totp_secrets_round_trip_through_base32(): void
    {
        $secret = Totp::generateSecret();

        self::assertMatchesRegularExpression('/^[A-Z2-7]{32}$/', $secret);
        self::assertMatchesRegularExpression('/^\d{6}$/', Totp::code($secret, 1));
    }

    public function test_razorpay_checkout_signatures_match_node(): void
    {
        foreach ($this->fixtures()['razorpay']['paymentVerification'] as $case) {
            self::assertSame(
                $case['signature'],
                Signature::checkout($case['providerOrderId'], $case['providerPaymentId'], $case['keySecret']),
            );
            self::assertTrue(Signature::verifyCheckout(
                $case['providerOrderId'],
                $case['providerPaymentId'],
                $case['signature'],
                $case['keySecret'],
            ));
            self::assertFalse(Signature::verifyCheckout(
                $case['providerOrderId'],
                $case['providerPaymentId'],
                str_repeat('0', 64),
                $case['keySecret'],
            ));
        }
    }

    public function test_razorpay_webhook_signatures_match_node_over_the_raw_body(): void
    {
        foreach ($this->fixtures()['razorpay']['webhook'] as $case) {
            self::assertSame($case['signature'], Signature::webhook($case['rawBody'], $case['webhookSecret']));
            self::assertTrue(Signature::verifyWebhook($case['rawBody'], $case['signature'], $case['webhookSecret']));

            // Re-serialising the JSON changes the bytes, and so must change the digest. This is the
            // failure mode that would reject every genuine webhook delivery.
            $reserialised = json_encode(json_decode($case['rawBody'], true));
            if ($reserialised !== $case['rawBody']) {
                self::assertFalse(
                    Signature::verifyWebhook($reserialised, $case['signature'], $case['webhookSecret']),
                );
            }
        }
    }

    public function test_missing_or_empty_signatures_are_refused(): void
    {
        self::assertFalse(Signature::sameHexDigest(str_repeat('a', 64), null));
        self::assertFalse(Signature::sameHexDigest(str_repeat('a', 64), ''));
    }
}
